package bottlesong

import (
	"fmt"
	"strconv"
)

// Recite returns the lyrics of the "Ten Green Bottles" song, starting with
// startBottles bottles and singing takeDown verses. Verses are separated by
// a blank line.
func Recite(startBottles, takeDown int) []string {
	var lyrics []string
	for n := startBottles; n > startBottles-takeDown; n-- {
		verse := []string{
			fmt.Sprintf("%s green bottles hanging on the wall,", bottleString(n)),
			fmt.Sprintf("%s green bottles hanging on the wall,", bottleString(n)),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green bottle%s hanging on the wall.", bottleString(n-1), plural(n-1)),
		}
		lyrics = append(lyrics, verse...)
		if n > startBottles-takeDown {
			lyrics = append(lyrics, "")
		}
	}
	return lyrics
}

// bottleString returns the number of bottles as a word, e.g. "ten" or "one".
func bottleString(n int) string {
	return Title(strconv.Itoa(n))
}

// plural returns "" for one bottle and "s" otherwise.
func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

